@Test("Execute calls repository once")
func executeCallsRepositoryOnce() async throws {
    let mockRepository = MockArchitectureRepository()
    await mockRepository.setGetFeaturesResult(.success([]))
    let useCase = ArchitectureUseCaseImpl(repository: mockRepository)

    _ = try await useCase.execute()

    let callCount = await mockRepository.getFeaturesCallCount
    #expect(callCount == 1)
}

actor MockArchitectureRepository: ArchitectureRepository {
    private(set) var getFeaturesResult: Result<[ArchitectureModel], Error> = .success([])
    private(set) var getFeaturesCallCount = 0

    func getFeatures() async throws -> [ArchitectureModel] {
        getFeaturesCallCount += 1

        switch getFeaturesResult {
        case let .success(features):
            return features
        case let .failure(error):
            throw error
        }
    }
}
